    let possible = row.(row_of.(x)) land col.(col_of.(x)) land box.(box_of.(x)) in 
    let v = min_bit_of.(possible) in
    current_val_tape.(!used_index) <- v;
    remaining_bits.(!used_index) <- left_bits_of.(possible);

    let r = row_of.(x) in
    let c = col_of.(x) in
    let b = box_of.(x) in

    row.(r) <- apow.(v) land row.(r);
    col.(c) <- apow.(v) land col.(c);
    box.(b) <- apow.(v) land box.(b);

    )
  )
  )
  done;
  for i = 0 to !all - 1 do 
    let j = used.(i) in 
    solution.(j / 9).(j mod 9) <- current_val_tape.(i) 
  done;
  Some solution
  (*with 
  | Invalid_argument _ -> None*)

let get_initial_grid (x : Model.problem) : int option array array =
  x.initial_grid

let solve_problem (problem : Model.problem) =
  problem |> get_initial_grid |> solve

